public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find a non-null, non-empty base string to generate candidates
    String base = null;
    for (String s : strings) {
        if (s != null && !s.isEmpty()) {
            base = s;
            break;
        }
    }
    if (base == null) { // all strings are null or empty
        return 0;
    }

    int maxLen = 0;
    // Try lengths from longest to shortest
    for (int len = base.length(); len >= 1; len--) {
        // Generate all substrings of this length from base
        for (int start = 0; start <= base.length() - len; start++) {
            String cand = base.substring(start, start + len);
            String rev = new StringBuilder(cand).reverse().toString();
            boolean allContain = true;

            for (String s : strings) {
                if (s == null) {
                    allContain = false;
                    break;
                }
                if (!(s.contains(cand) || s.contains(rev))) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                return len; // found the largest possible length
            }
        }
    }

    return 0; // no common substring found
}

public int findLargestSubstring(List<String> strings) {
    // Handle null or empty input
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Remove null elements to avoid NPE
    List<String> cleaned = new ArrayList<>();
    for (String s : strings) {
        if (s != null) {
            cleaned.add(s);
        }
    }
    if (cleaned.isEmpty()) {
        return 0;
    }

    // If only one non-null string, the longest substring is the string itself
    if (cleaned.size() == 1) {
        return cleaned.get(0).length();
    }

    // Find the shortest string to reduce the number of candidate substrings
    String base = cleaned.get(0);
    for (String s : cleaned) {
        if (s.length() < base.length()) {
            base = s;
        }
    }

    int baseLen = base.length();

    // Try lengths from longest to shortest
    for (int len = baseLen; len > 0; len--) {
        // Use a set to avoid duplicate substrings of the same length
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= baseLen; i++) {
            candidates.add(base.substring(i, i + len));
        }

        for (String candidate : candidates) {
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean allContain = true;
            for (String other : cleaned) {
                if (!(other.contains(candidate) || other.contains(reversed))) {
                    allContain = false;
                    break;
                }
            }
            if (allContain) {
                return len;
            }
        }
    }

    return 0; // No common substring found
}

