public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation of input
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    // ensure start and end are within bounds
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    // Quick win if start equals end
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency map: key "x,y" -> list of neighbor keys
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    java.util.function.IntFunction<String> key = p -> p[0] + "," + p[1];

    // Helper to add bidirectional edge
    java.util.function.BiConsumer<int[], int[]> addEdge = (a, b) -> {
        if (a[0] < 0 || a[0] >= n || a[1] < 0 || a[1] >= n ||
            b[0] < 0 || b[0] >= n || b[1] < 0 || b[1] >= n) {
            return; // ignore out-of-bounds edges
        }
        String ka = key.apply(a);
        String kb = key.apply(b);
        adj.computeIfAbsent(ka, k -> new java.util.ArrayList<>()).add(kb);
        adj.computeIfAbsent(kb, k -> new java.util.ArrayList<>()).add(ka);
    };

    // Build edges from paths array
    for (int[] path : paths) {
        if (path.length != 4) continue; // skip malformed
        int[] a = {path[0], path[1]};
        int[] b = {path[2], path[3]};
        addEdge.accept(a, b);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    String startKey = key.apply(start);
    String endKey   = key.apply(end);
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) {
        return "cannot be travelled";
    }
    if (start.length != end.length) {
        return "cannot be travelled";
    }
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length % 2 != 0) {
            continue;
        }
        int half = p.length / 2;
        int[] a = java.util.Arrays.copyOfRange(p, 0, half);
        int[] b = java.util.Arrays.copyOfRange(p, half, p.length);
        String keyA = java.util.Arrays.toString(a);
        String keyB = java.util.Arrays.toString(b);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Deque<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) {
            continue;
        }
        for (String nb : neighbors) {
            if (visited.add(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return null;
    }
    java.time.format.DateTimeFormatter formatter =
            java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.parse(date.trim(), formatter);
    } catch (java.time.format.DateTimeParseException e) {
        return null;
    }
    String month = localDate.getMonth()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    int day = localDate.getDayOfMonth();
    int year = localDate.getYear();
    String weekday = localDate.getDayOfWeek()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return month + " " + day + ", " + year + " is a " + weekday;
}

