public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Input date string must not be null or empty.");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input date must be in the format \"MM dd yyyy\".");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Month, day, and year must be numeric.", e);
    }
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date value.", e);
    }
    String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    String dayOfMonth = String.valueOf(localDate.getDayOfMonth());
    String yearString = String.valueOf(localDate.getYear());
    String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return monthName + " " + dayOfMonth + ", " + yearString + " is a " + weekday;
}

public int[] twoSum(int[] nums, int target) {
    // Handle null or insufficient length
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    if (nums.length < 2) {
        return new int[] { -1, -1 };
    }

    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[] { map.get(complement), i };
        }
        // Store the current number and its index
        // If the same number appears again, keep the first index only
        map.putIfAbsent(nums[i], i);
    }
    // In case no solution is found (should not happen as per problem statement)
    return new int[] { -1, -1 };
}

