public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = (int) Math.floor(n * 0.05);
    Arrays.sort(arr);
    long sum = 0;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    int count = n - 2 * trim;
    if (count <= 0) {
        return 0.0;
    }
    return sum / (double) count;
}

