    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * k;
    return remaining > 0 ? sum / (double) remaining : 0.0;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    // Sort the array to easily remove smallest and largest 5%
    java.util.Arrays.sort(arr);
    int n = arr.length;
    int k = n / 20; // Number of elements to remove from each side
    int start = k;
    int end = n - k; // exclusive
    if (start >= end) { // No elements remain after trimming
        return 0.0;
    }
    long sum = 0L;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    double avg = sum / (double)(end - start);
    return avg;
}

