public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        // Cannot pair all elements if the array length is odd
        return false;
    }

    // Count the frequency of each remainder when divided by k
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int mod = num % k;
        if (mod < 0) {
            mod += k; // Ensure non-negative remainder
        }
        remainderCount[mod]++;
    }

    // Check remainder 0: must have even count
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // If k is even, handle remainder k/2 which also needs even count
    if (k % 2 == 0) {
        int mid = k / 2;
        if (remainderCount[mid] % 2 != 0) {
            return false;
        }
    }

    // For all other remainders, counts must match their complementary remainder
    // Only need to iterate up to floor((k-1)/2)
    int upperLimit = k / 2;
    for (int r = 1; r < upperLimit; r++) {
        if (remainderCount[r] != remainderCount[k - r]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && count[k / 2] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled when k is even
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

