    while (remaining > 0) {
        // Ascending phase: pick smallest, then next greater, etc.
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending phase: pick largest, then next smaller, etc.
        for (int i = 25; i >= 0 && remaining > 0; i--) {
