public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Frequency array for all Unicode characters
    int[] freq = new int[65536];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    // helper functions
    java.util.function.IntSupplier findMin = () -> {
        for (int i = 0; i < freq.length; i++) {
            if (freq[i] > 0) return i;
        }
        return -1;
    };

    java.util.function.IntBinaryOperator findMinGreater = (last) -> {
        for (int i = last + 1; i < freq.length; i++) {
            if (freq[i] > 0) return i;
        }
        return -1;
    };

    java.util.function.IntSupplier findMax = () -> {
        for (int i = freq.length - 1; i >= 0; i--) {
            if (freq[i] > 0) return i;
        }
        return -1;
    };

    java.util.function.IntBinaryOperator findMaxLess = (last) -> {
        for (int i = last - 1; i >= 0; i--) {
            if (freq[i] > 0) return i;
        }
        return -1;
    };

    while (remaining > 0) {
        // Step 1: small to big
        int val = findMin.getAsInt();
        if (val == -1) break; // no more chars
        result.append((char) val);
        freq[val]--;
        remaining--;
        int last = val;

        while ((val = findMinGreater.applyAsInt(last)) != -1) {
            result.append((char) val);
            freq[val]--;
            remaining--;
            last = val;
        }

        // Step 4: big to small
        val = findMax.getAsInt();
        if (val == -1) break;
        result.append((char) val);
        freq[val]--;
        remaining--;
        int lastB = val;

        while ((val = findMaxLess.applyAsInt(lastB)) != -1) {
            result.append((char) val);
            freq[val]--;
            remaining--;
            lastB = val;
        }
    }

    return result.toString();
}

