public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    int curr = 0;
    for (int i = 2; i < n; i++) {
        curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start from step 1 (outside the array) and reach the top without any cost.
        return 0;
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two steps.");
    }
    int n = cost.length;
    int prev2 = cost[0];          // minimal cost to reach step 0
    int prev1 = cost[1];          // minimal cost to reach step 1
    if (n == 2) {
        return Math.min(prev2, prev1);
    }
    int current = 0;
    for (int i = 2; i < n; i++) {
        current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    // minimal cost to reach top is min cost to reach last two steps
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Only one step; we can skip paying any cost by starting beyond it.
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i (paying its cost).
    int dp0 = cost[0];      // Minimum cost to reach step 0
    int dp1 = cost[1];      // Minimum cost to reach step 1
    for (int i = 2; i < n; i++) {
        int cur = cost[i] + Math.min(dp0, dp1);
        dp0 = dp1;
        dp1 = cur;
    }
    // We can finish by stepping from step n-1 or n-2 to the top.
    return Math.min(dp0, dp1);
}

