public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    if (k < 0) return false;
    if (k == 0) return true; // empty substring is always present
    int n = s.length();
    // 2^k grows too fast; if k >= 31, it overflows int and 2^k > n
    if (k >= 31) return false;
    int total = 1 << k;
    if (n < total) return false; // cannot contain all substrings

    boolean[] seen = new boolean[total];
    int count = 0;
    for (int i = 0; i <= n - k; i++) {
        int code = 0;
        for (int j = i; j < i + k; j++) {
            code = (code << 1) | (s.charAt(j) - '0');
        }
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty()) {
        return false;
    }
    if (k <= 0) {
        return true; // trivially true for empty pattern
    }
    int n = s.length();
    if (k > n) {
        return false;
    }
    if (k > 20) { // 2^k would be > 1,048,576, too large for typical constraints
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int count = 1;
    int maskLimit = total - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }
    return count == total;
}

