    if (n < total) return false;
    boolean[] seen = new boolean[total];
    int mask = total - 1;   // mask to keep only k bits
    int count = 0;
    int curr = 0;
    for (int i = 0; i < n; i++) {
        // Build the integer representation of the current k-length window
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
