                }
            }
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    // Validate input parameters
    if (sentence == null || searchWord == null) {
        return -1;
    }

    // Trim the sentence and split it into words based on whitespace
    String trimmedSentence = sentence.trim();
    if (trimmedSentence.isEmpty()) {
        return -1;
    }

    String[] words = trimmedSentence.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        try {
            if (words[i].startsWith(searchWord)) {
                // Return 1-based index of the matching word
                return i + 1;
            }
        } catch (Exception e) {
            // If any unexpected exception occurs while checking startsWith,
            // skip this word and continue.
            continue;
        }
    }

    // No matching prefix found
    return -1;
}

