public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int res = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need an opening bracket before this closing bracket
                res++;
            } else {
                balance--;
            }
        }
    }
    // Any remaining unmatched '(' need closing brackets
    res += balance;
    return res;
}

public int minInsertions(String s) {
    if (s == null) {
