    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            balance++;
        } else if (ch == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // need to insert a '(' before this ')'
                insertions++;
            }
        }
    }
    // Any remaining unmatched '(' need a ')'
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
