    }
    int requiredLeftInsertions = 0;  // Number of unmatched right parentheses '(' needed
    int balance = 0;                 // Current count of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // Match with a previous '('
            } else {
                // No unmatched '(' available; need to insert one
                requiredLeftInsertions++;
            }
        } else {
            // Should not happen as per constraints; ignore or throw exception
            // Here we simply skip invalid characters
            continue;
        }
    }
    // Any remaining unmatched '(' need corresponding ')' insertions
    return requiredLeftInsertions + balance;
}

public int minInsertions(String s) {
