    }

    int insertionsNeeded = 0;
    int unmatchedLeft = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            unmatchedLeft++;
        } else if (c == ')') {
            if (unmatchedLeft > 0) {
                unmatchedLeft--;
            } else {
