                insertionsNeeded++;
            }
        } else {
            // Invalid character encountered
            throw new IllegalArgumentException("Input string contains invalid character: " + c);
        }
    }

    // Any remaining unmatched '(' need a corresponding ')'
    return insertionsNeeded + unmatchedLeft;
}

