public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long sumAbs = 0L;
    for (int i = 0; i < n; i++) {
        long value = 2L * i + 1L;
        sumAbs += Math.abs(value - n);
    }
    // Each operation decreases the total absolute difference by 2.
    long operations = sumAbs / 2;
    return (int) operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int startIndex = n / 2;
    if (n % 2 == 1) {
        startIndex++; // for odd n, start one index later
    }
    int operations = 0;
    for (int i = startIndex; i < n; i++) {
        operations += (2 * i + 1) - n;
    }
    return operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int t = n / 2; // floor(n/2)
    return (n % 2 == 0) ? t * t : t * (t + 1);
}

public int minOperations(int n) {
    if (n <= 1) return 0;
    int s = (n + 1) / 2;          // ceil(n/2)
    int m = n - s;                // number of surplus indices
    long ops = (long) s * m;      // use long to avoid overflow during multiplication
    return (int) ops;              // result fits in int for the expected constraints
}

