    for (int num : nums) {
        // Maximum subarray sum ending here
        maxEnding = Math.max(num, maxEnding + num);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        // Minimum subarray sum ending here
        minEnding = Math.min(num, minEnding + num);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    long absMax = Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
    // Cast to int (converting negative to positive for abs, safe for typical constraints)
    return (int) absMax;
}

