public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient for int range
    int fibCount = 0;
    fib[fibCount++] = 1; // F1
    fib[fibCount++] = 1; // F2
    while (true) {
        int next = fib[fibCount - 1] + fib[fibCount - 2];
        if (next > k) {
            break;
        }
        fib[fibCount++] = next;
    }

    int remaining = k;
    int count = 0;
    // Greedy algorithm: pick the largest Fibonacci number not exceeding remaining
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            int times = remaining / fib[i];
            count += times;
            remaining -= times * fib[i];
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1); // F1
    fib.add(1); // F2
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }

    int count = 0;
    while (k > 0) {
        // Find the largest Fibonacci number <= k
        int i = fib.size() - 1;
        while (fib.get(i) > k) {
            i--;
        }
        k -= fib.get(i);
        count++;
    }

    return count;
}

