        long next = (long) fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add((int) next);
    }

    // Greedy subtraction to obtain the minimal count
    int remaining = k;
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    int[] fib = new int[47]; // Enough to cover Fibonacci numbers up to Integer.MAX_VALUE
    fib[0] = 1;
    fib[1] = 1;
    int len = 2;
    while (len < fib.length) {
        int next = fib[len - 1] + fib[len - 2];
        if (next > k || next < 0) { // Stop if next would overflow or exceed k
            break;
        }
        fib[len] = next;
        len++;
    }
    int remaining = k;
    int count = 0;
    for (int i = len - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) break;
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;

    // Greedy algorithm: subtract largest possible Fibonacci number each time
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return (k - 1) < factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    if (n < 1 || k < 1) {
        return -1;
    }
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    Collections.reverse(large);
    List<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    if (k > all.size()) {
        return -1;
    }
    return all.get(k - 1);
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    int smallCount = 0;
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            smallCount++;
        }
    }
    int totalFactors;
    if (limit * limit == n) {
        totalFactors = 2 * smallCount - 1;
    } else {
        totalFactors = 2 * smallCount;
    }
    if (k > totalFactors) {
        return -1;
    }
    if (k <= smallCount) {
        int count = 0;
        for (int i = 1; i <= limit; i++) {
            if (n % i == 0) {
                count++;
                if (count == k) {
                    return i;
                }
            }
        }
    } else {
        int remaining = k - smallCount;
        for (int i = limit; i >= 1; i--) {
            if (n % i == 0) {
                if (i * i == n) {
                    continue; // skip duplicate sqrt
                }
                remaining--;
                if (remaining == 0) {
                    return n / i;
                }
            }
        }
    }
    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int complement = n / i;
            if (complement != i) {
                large.add(complement);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int indexInLarge = k - small.size() - 1; // 0‑based index within reversed large part
        int reverseIndex = large.size() - 1 - indexInLarge;
        return large.get(reverseIndex);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if current and top are the same letter with opposite cases
            if (Math.abs(top - current) == 32) {
                stack.setLength(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(current); // push current character
    }
    return stack.toString();
}

public String makeGood(String s) {
