    }
    StringBuilder stack = new StringBuilder();
    char[] chars = s.toCharArray();
    for (char c : chars) {
        if (stack.length() > 0) {
            char top = stack.charAt(stack.length() - 1);
            // Check if top and c represent the same letter in opposite cases
            if (Character.toLowerCase(top) == Character.toLowerCase(c) && top != c) {
                // Remove the adjacent pair
                stack.deleteCharAt(stack.length() - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public String makeGood(String s) {
    // Handle null or empty input gracefully
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Use a StringBuilder as a stack to build the resulting string
    StringBuilder stack = new StringBuilder();

    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if top and current form a bad pair:
            // one is upper case, the other lower case, and the same letter ignoring case
            if (Character.isUpperCase(top) != Character.isUpperCase(c)
                    && Character.toLowerCase(top) == Character.toLowerCase(c)) {
                // Remove the bad pair
                stack.setLength(len - 1);
                continue;
            }
        }
        // If not a bad pair, push current character onto the stack
        stack.append(c);
    }

    // The remaining characters form the "good" string
    return stack.toString();
}

