}

private void dfs(int pos, java.util.Set<String> used, String s, int[] maxRef) {
    if (pos == s.length()) {
        if (used.size() > maxRef[0]) {
            maxRef[0] = used.size();
        }
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, s, maxRef);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) return 0;
    int n = s.length();
    int max = 1;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        boolean unique = true;
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) { unique = false; break; }
                start = i + 1;
            }
        }
        if (!unique) continue;
        String sub = s.substring(start);
        if (!seen.add(sub)) continue;
        int count = seen.size();
        if (count > max) max = count;
    }
    return max;
}

