            backtrack(s, i, used, best);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("./")) {
            // stay in current folder, nothing to do
            continue;
        } else if (log.equals("../")) {
            // move up one folder if possible
            if (depth > 0) {
                depth--;
            }
        } else if (log.endsWith("/")) {
            // enter a new folder
            depth++;
        }
        // any other format is ignored as it does not represent a valid operation
    }
    // depth now represents how many levels away from the main folder we are
    return depth;
}

