public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Long> queue = new LinkedList<>();
    for (int i=0; i<=9; i++) {
        long num = i;
        if (num >= low && num <= high) result.add((int)num);
        queue.offer(num);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue; // skip expansions beyond high
        long lastDigit = num % 10;
        long next1 = num *10 + (lastDigit -1);
        long next2 = num *10 + (lastDigit +1);
        // careful about lastDigit-1>=0
        if (lastDigit>0) {
            if (next1 <= high) {
                queue.offer(next1);
                if (next1 >= low && next1 <= high) result.add((int)next1);
            }
        }
        if (lastDigit<9) {
            if (next2 <= high) {
                queue.offer(next2);
                if (next2 >= low && next2 <= high) result.add((int)next2);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Set<Integer> seen = new HashSet<>();

    // Handle zero
    if (low <= 0 && 0 <= high) {
        seen.add(0);
    }

    Queue<Long> queue = new LinkedList<>();

    for (int i = 1; i <= 9; i++) {
        long num = i;
        if (num >= low && num <= high) seen.add((int)num);
        queue.offer(num);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;

        long lastDigit = num % 10;

        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                if (next >= low) seen.add((int) next);
                queue.offer(next);
            }
        }

        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                if (next >= low) seen.add((int) next);
                queue.offer(next);
            }
        }
    }

    result.addAll(seen);
    Collections.sort(result);
    return result;
}

