public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    int lowBound = Math.max(low, 0);
    if (high < lowBound) return result;
    Queue<Long> queue = new LinkedList<>();
    Set<Long> visited = new HashSet<>();
    for (int i=0;i<=9;i++){
        long val = i;
        queue.offer(val);
        visited.add(val);
    }
    while (!queue.isEmpty()){
        long num = queue.poll();
        if (num > high) continue;
        if (num >= lowBound) {
            result.add((int)num);
        }
        int lastDigit = (int)(num % 10);
        if (num > 0){ // generate children
            if (lastDigit > 0){
                long child = num*10 + (lastDigit-1);
                if (child <= high && !visited.contains(child)){
                    queue.offer(child);
                    visited.add(child);
                }
            }
            if (lastDigit < 9){
                long child = num*10 + (lastDigit+1);
                if (child <= high && !visited.contains(child)){
                    queue.offer(child);
                    visited.add(child);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0L;
    long divisor = 1L;
    while (divisor <= n) {
        long high = n / (divisor * 10L);
        long cur = (n / divisor) % 10L;
        long low = n % divisor;
        count += high * divisor;
        if (cur > 1) {
            count += divisor;
        } else if (cur == 1) {
            count += low + 1;
        }
        divisor *= 10L;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
