public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int value = Math.abs(n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (value > 0) {
        int digit = value % 10;
        sb.append((char) ('0' + digit));
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    // Determine if the number is negative
    boolean negative = n < 0;

    // Use long to safely handle Math.abs(Integer.MIN_VALUE)
    long absVal = Math.abs((long) n);

    // Convert the absolute value to a string
    String number = Long.toString(absVal);
    int length = number.length();

    // Build the formatted string with dots
    StringBuilder formatted = new StringBuilder();

    // First group can have 1-3 digits
    int firstGroupSize = length % 3;
    if (firstGroupSize == 0) {
        firstGroupSize = 3;
    }

    formatted.append(number.substring(0, firstGroupSize));
    int index = firstGroupSize;

    while (index < length) {
        formatted.append('.');
        formatted.append(number.substring(index, index + 3));
        index += 3;
    }

    // Prepend minus sign if needed
    return negative ? "-" + formatted.toString() : formatted.toString();
}

