public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n <= 1) return 1;
    Arrays.sort(A);
    boolean[] used = new boolean[n];
    Map<Long, Integer> memo = new HashMap<>();
    Function<int[], Integer> isSquare = sum -> {
        int root = (int) Math.sqrt(sum);
        return (root * root == sum) ? 1 : 0;
    };

    return dfs(-1, 0);

    int dfs(int lastIndex, int count) {
        if (count == n) return 1;
        long key = (((long) (lastIndex + 1)) << 32) | count << 1 | (lastIndex == -1 ? 0 : 1);
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int total = 0;
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            // skip duplicates: if current equals previous and previous not used in this branch
            if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
            if (lastIndex == -1 || isSquare(sum(lastIndex, i)) == 1) {
                used[i] = true;
                total += dfs(i, count + 1);
                used[i] = false;
            }
        }
        memo.put(key, total);
        return total;
    }

    int sum(int a, int b) {
        return A[a] + A[b];
    }
}

