public static int squarePermutations(int[] A) {
    if (A == null) return 0;
    int n = A.length;
    java.util.Arrays.sort(A);
    int allMask = (1 << n) - 1;
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1]) continue; // skip duplicate starting values
        total += dfs(i, 1 << i, n, allMask, A, memo);
    }
    return total;
}

private static int dfs(int last, int mask, int n, int allMask, int[] A, java.util.Map<Long, Integer> memo) {
    if (mask == allMask) return 1;
    long key = ((long) mask << 5) | last; // 5 bits enough for n <= 32
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    int sum = 0;
    for (int j = 0; j < n; j++) {
        if ((mask & (1 << j)) != 0) continue; // already used
        if (j > 0 && A[j] == A[j - 1] && (mask & (1 << (j - 1))) == 0) continue; // skip duplicates
        int val = A[last] + A[j];
        int root = (int) Math.sqrt(val);
        if (root * root == val) {
            sum += dfs(j, mask | (1 << j), n, allMask, A, memo);
        }
    }
    memo.put(key, sum);
    return sum;
}

