    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int row = 0, col = 0;
    boolean up = true;

    while (idx < m * n) {
        result[idx++] = mat[row][col];

        if (up) {
            if (col == n - 1) { // hit last column, move down
                row++;
                up = false;
            } else if (row == 0) { // hit first row, move right
                col++;
                up = false;
            } else { // move diagonally up-right
                row--;
                col++;
            }
        } else { // moving down-left
            if (row == m - 1) { // hit last row, move right
                col++;
                up = true;
            } else if (col == 0) { // hit first column, move down
                row++;
                up = true;
            } else { // move diagonally down-left
                row++;
                col--;
            }
        }
    }
    return result;
}

