public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    for (int prefix = 1; prefix <= 9; prefix++) {
        dfs(prefix, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int digit = 0; digit <= 9; digit++) {
        long next = (long) current * 10 + digit;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) { 
   if (n <= 0) return new ArrayList<>();
   ArrayList<Integer> res = new ArrayList<>(n);
   int cur = 1;
   for (int i=0; i<n; i++) {
      res.add(cur);
      if (cur*10 <= n) {
          cur *= 10;
      } else {
         while (cur%10 == 9 || cur+1 > n) {
            cur /=10;
         }
         cur++;
      }
   }
   return res;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            if (curr % 10 != 9 && curr + 1 <= n) {
                curr++;
            } else {
                while ((curr / 10) % 10 == 9 || curr + 1 > n) {
                    curr /= 10;
                }
                curr++;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    int cur = 1;
    while (result.size() < n) {
        result.add(cur);
        if ((long)cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            while ((cur / 10) % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) return;
    result.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = (long) current * 10 + d;
        if (next > n) break;
        dfs((int) next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

