        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            min = Math.min(min, dp[i - square] + 1);
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize all values to a large number
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        // Try all possible perfect squares less than or equal to i
        for (int square = 1; square * square <= i; square++) {
            int sq = square * square;
            if (dp[i - sq] + 1 < dp[i]) {
                dp[i] = dp[i - sq] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = n + 1; // upper bound for the minimum count
        for (int j = 1; j * j <= i; j++) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

